CREATE TABLE IF NOT EXISTS tenant(id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS practitioner(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), display_name TEXT NOT NULL, ptin_last4 TEXT, efin TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,display_name));
CREATE TABLE IF NOT EXISTS client(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), identity_key TEXT NOT NULL, first_name TEXT, last_name TEXT, dob TEXT, ssn_enc BLOB, ssn_last4 TEXT, phone_enc BLOB, email_enc BLOB, address_enc BLOB, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,identity_key));
CREATE TABLE IF NOT EXISTS tax_folder(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), client_id TEXT NOT NULL REFERENCES client(id), tax_year INTEGER NOT NULL CHECK(tax_year BETWEEN 1900 AND 2200), status TEXT NOT NULL DEFAULT 'OPEN', assigned_practitioner_id TEXT REFERENCES practitioner(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,client_id,tax_year));
CREATE TABLE IF NOT EXISTS tax_return(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), folder_id TEXT NOT NULL REFERENCES tax_folder(id), source_return_id TEXT NOT NULL, return_type TEXT, filing_status TEXT, federal_status TEXT, federal_refund_cents INTEGER, federal_accepted_at TEXT, state_code TEXT, state_status TEXT, state_refund_cents INTEGER, state_accepted_at TEXT, agi_cents INTEGER, marked_complete INTEGER NOT NULL DEFAULT 0, marked_paid INTEGER NOT NULL DEFAULT 0, source_hash TEXT NOT NULL, imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,source_return_id));
CREATE TABLE IF NOT EXISTS bank_product(id TEXT PRIMARY KEY, return_id TEXT NOT NULL UNIQUE REFERENCES tax_return(id), bank_name TEXT, product TEXT, routing_enc BLOB, account_enc BLOB, routing_last4 TEXT, account_last4 TEXT, funded_at TEXT, advance_requested_cents INTEGER, advance_paid_cents INTEGER);
CREATE TABLE IF NOT EXISTS fee_ledger(id TEXT PRIMARY KEY, return_id TEXT NOT NULL REFERENCES tax_return(id), fee_type TEXT NOT NULL, assessed_cents INTEGER NOT NULL DEFAULT 0, paid_cents INTEGER NOT NULL DEFAULT 0, paid_at TEXT, UNIQUE(return_id,fee_type));
CREATE TABLE IF NOT EXISTS return_form(id TEXT PRIMARY KEY, return_id TEXT NOT NULL REFERENCES tax_return(id), form_code TEXT NOT NULL, present INTEGER NOT NULL, UNIQUE(return_id,form_code));
CREATE TABLE IF NOT EXISTS status_event(id TEXT PRIMARY KEY, return_id TEXT NOT NULL REFERENCES tax_return(id), authority TEXT NOT NULL, status_code TEXT, occurred_at TEXT, payload_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reconciliation(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), return_id TEXT NOT NULL REFERENCES tax_return(id), check_name TEXT NOT NULL, expected_cents INTEGER, actual_cents INTEGER, variance_cents INTEGER, severity TEXT NOT NULL, disposition TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(return_id,check_name));
CREATE TABLE IF NOT EXISTS case_note(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), folder_id TEXT NOT NULL REFERENCES tax_folder(id), category TEXT NOT NULL CHECK(category IN ('CLIENT_CONTACT','IRS_CONTACT','DOCUMENTATION','REVIEW','GENERAL')), subject TEXT NOT NULL, note_enc BLOB NOT NULL, visibility TEXT NOT NULL DEFAULT 'TEAM' CHECK(visibility IN ('PRIVATE','TEAM','SUPERVISOR')), author_id TEXT NOT NULL, follow_up_at TEXT, status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','PENDING','COMPLETED','CANCELLED')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS remedy_action(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), folder_id TEXT NOT NULL REFERENCES tax_folder(id), issue_code TEXT NOT NULL, remedy_type TEXT NOT NULL CHECK(remedy_type IN ('AMEND_RETURN','RESPOND_NOTICE','IDENTITY_VERIFY','TRACE_REFUND','RELEASE_HOLD','APPEAL','PAYMENT_PLAN','PENALTY_RELIEF','INJURED_SPOUSE','OTHER')), description_enc BLOB NOT NULL, authority TEXT, due_at TEXT, owner_id TEXT, status TEXT NOT NULL DEFAULT 'PROPOSED' CHECK(status IN ('PROPOSED','APPROVED','IN_PROGRESS','SUBMITTED','RESOLVED','DENIED','CANCELLED')), outcome_enc BLOB, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS credit_adjustment(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), return_id TEXT NOT NULL REFERENCES tax_return(id), item_type TEXT NOT NULL CHECK(item_type IN ('CREDIT','ADJUSTMENT')), tax_code TEXT NOT NULL, description TEXT, claimed_cents INTEGER NOT NULL DEFAULT 0, allowed_cents INTEGER, adjusted_cents INTEGER, variance_cents INTEGER GENERATED ALWAYS AS (COALESCE(allowed_cents,claimed_cents)+COALESCE(adjusted_cents,0)-claimed_cents) STORED, source TEXT NOT NULL DEFAULT 'RETURN', status TEXT NOT NULL DEFAULT 'REPORTED', effective_at TEXT, evidence_ref TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(return_id,item_type,tax_code,source,effective_at));
CREATE TABLE IF NOT EXISTS irs_tc846(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), return_id TEXT NOT NULL REFERENCES tax_return(id), transcript_year INTEGER NOT NULL, transaction_date TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), cycle_code TEXT, transcript_received_at TEXT, source_document_hash TEXT NOT NULL, matched_funding INTEGER NOT NULL DEFAULT 0, match_confidence REAL, notes_enc BLOB, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(return_id,transcript_year,transaction_date,amount_cents,source_document_hash));
CREATE TABLE IF NOT EXISTS sbtpg_funding(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), return_id TEXT NOT NULL REFERENCES tax_return(id), external_reference TEXT, expected_refund_cents INTEGER, received_cents INTEGER, fees_withheld_cents INTEGER, taxpayer_disbursement_cents INTEGER, funding_status TEXT NOT NULL DEFAULT 'PENDING' CHECK(funding_status IN ('PENDING','RECEIVED','PARTIAL','FUNDED','RETURNED','OFFSET','HOLD','CANCELLED')), received_at TEXT, disbursed_at TEXT, disbursement_method TEXT, trace_number_enc BLOB, trace_last4 TEXT, source_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,external_reference,source_hash));
CREATE TABLE IF NOT EXISTS integration_connection(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), service TEXT NOT NULL, environment TEXT NOT NULL CHECK(environment IN ('TEST','PRODUCTION')), credential_ref TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DISABLED', UNIQUE(tenant_id,service,environment));
CREATE TABLE IF NOT EXISTS integration_message(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), connection_id TEXT REFERENCES integration_connection(id), correlation_id TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('OUTBOUND','INBOUND')), message_type TEXT NOT NULL, payload_enc BLOB, payload_hash TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,correlation_id,direction,message_type));
CREATE TABLE IF NOT EXISTS taxpayer_authorization(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), client_id TEXT NOT NULL REFERENCES client(id), authorization_type TEXT NOT NULL CHECK(authorization_type IN ('FORM_2848','FORM_8821','OTHER')), tax_form TEXT NOT NULL, tax_period_start TEXT NOT NULL, tax_period_end TEXT NOT NULL, caf_last4 TEXT, status TEXT NOT NULL CHECK(status IN ('DRAFT','SIGNED','SUBMITTED','ACCEPTED','REJECTED','REVOKED','EXPIRED')), document_hash TEXT NOT NULL, effective_at TEXT, expires_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS integration_job(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), service TEXT NOT NULL CHECK(service IN ('TDS','SOR','MEF','TINM','IRIS','ACA','TAX_PRO_ACCOUNT')), operation TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, authorization_id TEXT REFERENCES taxpayer_authorization(id), request_enc BLOB NOT NULL, request_hash TEXT NOT NULL, idempotency_key TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 100, status TEXT NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','LEASED','SUCCEEDED','RETRY','FAILED','BLOCKED_AUTH','DISABLED')), available_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, leased_by TEXT, lease_expires_at TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 8, last_error_code TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT, UNIQUE(tenant_id,service,idempotency_key));
CREATE TABLE IF NOT EXISTS worker_node(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), worker_type TEXT NOT NULL, version TEXT NOT NULL, capabilities_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ONLINE','DRAINING','OFFLINE','QUARANTINED')), started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, heartbeat_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_job_at TEXT);
CREATE TABLE IF NOT EXISTS transcript_snapshot(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), client_id TEXT NOT NULL REFERENCES client(id), return_id TEXT REFERENCES tax_return(id), transcript_type TEXT NOT NULL, tax_year INTEGER NOT NULL, requested_at TEXT NOT NULL, received_at TEXT, source_message_id TEXT REFERENCES integration_message(id), content_enc BLOB, content_hash TEXT, cycle_code TEXT, cycle_year INTEGER, cycle_week INTEGER CHECK(cycle_week BETWEEN 1 AND 53), cycle_day INTEGER CHECK(cycle_day BETWEEN 0 AND 7), prior_snapshot_id TEXT REFERENCES transcript_snapshot(id), change_summary_enc BLOB, status TEXT NOT NULL CHECK(status IN ('REQUESTED','RECEIVED','PARSED','UNCHANGED','CHANGED','ERROR')), UNIQUE(tenant_id,client_id,transcript_type,tax_year,content_hash));
CREATE TABLE IF NOT EXISTS realtime_event(id INTEGER PRIMARY KEY AUTOINCREMENT, event_uuid TEXT NOT NULL UNIQUE, tenant_id TEXT NOT NULL REFERENCES tenant(id), channel TEXT NOT NULL, event_type TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT);
CREATE TABLE IF NOT EXISTS replication_outbox(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, sequence_no INTEGER NOT NULL, event_type TEXT NOT NULL, payload_enc BLOB NOT NULL, payload_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TEXT, UNIQUE(tenant_id,aggregate_type,aggregate_id,sequence_no));
CREATE TABLE IF NOT EXISTS audit_event(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenant(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_client_tenant_name ON client(tenant_id,last_name,first_name);
CREATE INDEX IF NOT EXISTS idx_folder_year ON tax_folder(tenant_id,tax_year,status);
CREATE INDEX IF NOT EXISTS idx_outbox_dispatch ON replication_outbox(status,next_attempt_at,created_at);
CREATE INDEX IF NOT EXISTS idx_case_note_followup ON case_note(tenant_id,status,follow_up_at);
CREATE INDEX IF NOT EXISTS idx_remedy_due ON remedy_action(tenant_id,status,due_at);
CREATE INDEX IF NOT EXISTS idx_846_match ON irs_tc846(tenant_id,matched_funding,transaction_date);
CREATE INDEX IF NOT EXISTS idx_sbtpg_status ON sbtpg_funding(tenant_id,funding_status,received_at);
CREATE INDEX IF NOT EXISTS idx_job_claim ON integration_job(status,available_at,priority,created_at);
CREATE INDEX IF NOT EXISTS idx_worker_health ON worker_node(tenant_id,status,heartbeat_at);
CREATE INDEX IF NOT EXISTS idx_transcript_history ON transcript_snapshot(tenant_id,client_id,tax_year,received_at);
CREATE INDEX IF NOT EXISTS idx_realtime_cursor ON realtime_event(tenant_id,id);
CREATE VIEW IF NOT EXISTS v_return_reconciliation AS SELECT r.id return_id,r.tenant_id,f.tax_year,r.source_return_id,r.federal_status,r.federal_refund_cents,COALESCE(SUM(l.assessed_cents),0) total_fees_cents,COALESCE(SUM(l.paid_cents),0) total_paid_cents,COALESCE(SUM(l.assessed_cents-l.paid_cents),0) fee_balance_cents FROM tax_return r JOIN tax_folder f ON f.id=r.folder_id LEFT JOIN fee_ledger l ON l.return_id=r.id GROUP BY r.id;
CREATE VIEW IF NOT EXISTS v_refund_funding_reconciliation AS SELECT r.id return_id,r.tenant_id,r.federal_refund_cents,COALESCE(t.amount_cents,0) tc846_cents,COALESCE(s.received_cents,0) sbtpg_received_cents,COALESCE(s.fees_withheld_cents,0) fees_withheld_cents,COALESCE(s.taxpayer_disbursement_cents,0) taxpayer_disbursement_cents,COALESCE(t.amount_cents,0)-COALESCE(s.received_cents,0) irs_to_sbtpg_variance_cents,COALESCE(s.received_cents,0)-COALESCE(s.fees_withheld_cents,0)-COALESCE(s.taxpayer_disbursement_cents,0) sbtpg_allocation_variance_cents FROM tax_return r LEFT JOIN (SELECT return_id,SUM(amount_cents) amount_cents FROM irs_tc846 GROUP BY return_id) t ON t.return_id=r.id LEFT JOIN (SELECT return_id,SUM(received_cents) received_cents,SUM(fees_withheld_cents) fees_withheld_cents,SUM(taxpayer_disbursement_cents) taxpayer_disbursement_cents FROM sbtpg_funding GROUP BY return_id) s ON s.return_id=r.id;
